// Normalize the payload the voice agent (backend/routes/voice.py) sends:
// { service, address, phone, customer_name, preferred_day, preferred_time, call_id }
// address/phone are required fields (booking is never confirmed without them);
// preferred_day/preferred_time are optional and may be null.
const body = $input.first().json.body || $input.first().json;
return [{
  json: {
    service: body.service || 'unspecified',
    address: body.address || 'unspecified',
    phone: body.phone || 'unspecified',
    customer_name: body.customer_name || 'Caller',
    preferred_day: body.preferred_day || null,
    preferred_time: body.preferred_time || null,
    call_id: body.call_id || null,
    received_at: new Date().toISOString()
  }
}];
